import java.util.*;

public class P2 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalChars = scanner.nextInt();
        scanner.nextLine();
        String lineInput = scanner.nextLine();

        int maxWord = 0;
        int currentWord = 0;
        int totalWords = 0;
        int parenthesesDepth = 0;
        boolean outsideWordFlag = false;
        boolean insideWordFlag = false;
        boolean insideParenthesesFlag = false;

        for (int idx = 0; idx < totalChars; idx++) {
            char c = lineInput.charAt(idx);
            if (c == '(') {
                insideParenthesesFlag = true;
                parenthesesDepth++;
                if (maxWord < currentWord)
                    maxWord = currentWord;
                currentWord = 0;
                outsideWordFlag = false;
            } else if (c == ')') {
                insideParenthesesFlag = false;
                parenthesesDepth = 0;
                if (parenthesesDepth > 0) {
                    totalWords++;
                }
            } else {
                if (parenthesesDepth > 0) {
                    insideParenthesesFlag = true;
                }
            }

            if (idx == totalChars)
                break;

            if (c != ')' && c != '(') {
                if (!insideParenthesesFlag) {
                    if (c == '_') {
                        if (maxWord < currentWord)
                            maxWord = currentWord;
                        currentWord = 0;
                        outsideWordFlag = false;
                    } else {
                        outsideWordFlag = true;
                    }

                    if (outsideWordFlag) {
                        currentWord++;
                    }
                } else {
                    outsideWordFlag = false;
                    if (c == '_') {
                        if (parenthesesDepth > 0)
                            totalWords++;
                        parenthesesDepth = 0;
                        insideWordFlag = false;
                    } else {
                        insideWordFlag = true;
                    }

                    if (insideWordFlag) {
                        parenthesesDepth++;
                    }
                }
            }
        }

        if (maxWord < currentWord)
            maxWord = currentWord;

        System.out.println(maxWord + " " + totalWords);
    }
}
